import json
E_={}
K=json.loads(open('tools/claves.json').read())
PL=json.loads(open('tools/planes.json').read())
def plan_(id,pl): return [{'t':t,'eq':e} if e else {'t':t} for t,e in PL[id]] if id in PL else [{'t':t} for t in pl]
def E(id,tema,que,pistas,no,plan): E_[id]={'tema':tema,'que':que,'pistas':pistas,'clave':K[id],'no':[{'t':a,'p':b} for a,b in no],'plan':plan_(id,plan)}
E('cie-001','Física: lanzamiento en parábola','Es cuando algo sale disparado hacia arriba y hacia adelante, sube, se frena y cae dibujando una curva, como un balón pateado.',
 ['dice que el balón se patea con un ángulo de $30°$ (sale inclinado, no recto)','dan la rapidez con que sale: $20$ m/s','piden el alcance: qué tan lejos cae, en horizontal'],
 [('Caída libre','Se parece porque también actúa la gravedad. Pero en caída libre el objeto solo sube o baja en línea recta y aquí piden distancia hacia adelante.'),('Movimiento a velocidad constante','Se parece porque el balón avanza hacia adelante. Pero si fuera constante no habría curva: aquí la gravedad lo va frenando hacia arriba y acelerando hacia abajo.')],
 ['Anoto lo que me dan: rapidez $20$ m/s, ángulo $30°$ y gravedad $10$.','Busco la fórmula del alcance, que sirve justo para este tipo de lanzamiento.','Reemplazo los números en la fórmula y hago la cuenta con calculadora.','Reviso que la respuesta esté en metros y que tenga sentido para un balón.'])
E('cie-002','Física: movimiento que va ganando velocidad','Es cuando algo arranca y va yendo cada vez más rápido, de forma pareja, como un carro que acelera suave.',
 ['dice que parte del reposo (arranca quieto)','dan una aceleración de $3$ m/s²: cada segundo gana $3$ m/s más de velocidad','piden la distancia recorrida en $4$ s'],
 [('Movimiento a velocidad constante','Se parece porque algo se mueve y piden distancia. Pero ahí la velocidad no cambia y la cuenta es velocidad por tiempo; aquí la velocidad va aumentando.'),('Caída libre','Se parece porque también hay aceleración. Pero en caída libre acelera la gravedad ($10$ m/s²) y aquí la aceleración la da el enunciado: $3$ m/s².')],
 ['Anoto los datos: arranca quieto, aceleración $3$ y tiempo $4$ s.','Como arranca quieto, uso la fórmula de distancia con aceleración: la mitad de la aceleración por el tiempo al cuadrado.','Reemplazo: la mitad de $3$ es $1,5$; el tiempo al cuadrado es $16$; multiplico.','Miro que el resultado esté en metros.'])
E('cie-003','Física: electricidad, ley de Ohm','Es la regla que une tres cosas: el voltaje (la fuerza que empuja), la resistencia (lo que frena) y la corriente (lo que realmente pasa).',
 ['dan una resistencia de $6$ Ω y un voltaje de $12$ V','piden la corriente (cuánta electricidad pasa)','hay una sola resistencia, sin más aparatos'],
 [('Potencia eléctrica','Se parece porque también se usan voltios. Pero la potencia se mide en vatios (W) y aquí piden la corriente, que se mide en amperios (A).'),('Circuitos con varias resistencias','Se parece porque es un circuito. Pero ahí hay que combinar resistencias primero; aquí hay una sola, así que no hay nada que combinar.')],
 ['Escribo la regla de Ohm: voltaje igual a corriente por resistencia.','Como piden la corriente, la dejo sola: corriente es voltaje dividido entre resistencia.','Reemplazo: $12$ dividido entre $6$.','Pongo la unidad: amperios (A).'])
E('cie-004','Química: balancear una reacción','Es lograr que en una reacción química haya los mismos átomos antes y después de la flecha, porque los átomos no se crean ni se destruyen.',
 ['te dan una reacción escrita con fórmulas ($C_3H_8 + O_2 \\to CO_2 + H_2O$)','piden un coeficiente, el número que va delante de una fórmula','no dan gramos ni cantidades'],
 [('Cálculos con moles y gramos','Se parece porque es química con números. Pero ahí te dan cantidades; aquí solo te dan la ecuación y piden equilibrarla.'),('Nombrar compuestos','Se parece porque aparecen fórmulas. Pero nadie pregunta cómo se llama cada compuesto.')],
 ['Cuento cuántos átomos de carbono (C) hay a la izquierda: $3$. Entonces el $CO_2$ lleva un $3$ delante.','Cuento los hidrógenos (H): hay $8$. Entonces el agua ($H_2O$) lleva un $4$ delante.','Ahora cuento todo el oxígeno que quedó a la derecha: $6$ de los $CO_2$ y $4$ del agua, o sea $10$ átomos.','Cada $O_2$ tiene $2$ átomos, así que $10$ entre $2$ da $5$ delante del $O_2$.'])
E('cie-005','Biología: herencia de padres a hijos (genética)','Es calcular qué probabilidad hay de que los hijos hereden cierta característica, usando las letras que representan los genes de cada papá.',
 ['aparecen letras como $Aa$: son los genes de cada planta','piden la probabilidad de que un hijo sea $aa$','se cruzan solo dos plantas, un solo cruce'],
 [('División de las células','Se parece porque también es biología de genes. Pero aquí nadie pregunta cómo se divide la célula, sino qué se hereda.'),('Evolución','Se parece porque habla de descendientes. Pero la evolución trata de poblaciones durante muchas generaciones; aquí es un solo cruce.')],
 ['Escribo los genes de cada planta: una es $Aa$ y la otra también.','Dibujo una cuadrícula de $2$ por $2$ (cuadro de Punnett): arriba los genes de una, al lado los de la otra.','Lleno cada casilla combinando una letra de arriba con una de al lado: salen $AA$, $Aa$, $Aa$ y $aa$.','Cuento: de $4$ casillas, solo $1$ es $aa$. La probabilidad es $1$ de $4$.'])
E('cie-006','Física: lentes (óptica)','Es estudiar cómo un lente, como el de una lupa, junta la luz y forma una imagen de un objeto.',
 ['dice lente convergente (el que junta la luz)','dan la distancia focal $f=10$ cm y el objeto a $15$ cm','piden cómo es la imagen: real o virtual, derecha o invertida'],
 [('Espejos','Se parece porque también forman imágenes. Pero un espejo rebota la luz y un lente la deja pasar; aquí la luz atraviesa el lente.'),('Refracción con ángulos','Se parece porque la luz cambia al pasar por el lente. Pero aquí no dan ángulos ni piden calcular cuánto se desvía.')],
 ['Anoto: distancia focal $10$ cm y objeto a $15$ cm.','Uso la ecuación del lente para hallar a qué distancia se forma la imagen.','Me fijo en el resultado: si sale positivo, la imagen es real e invertida.','Reviso las opciones y elijo la que coincide con la distancia que calculé.'])
E('cie-008','Química: gases ideales','Es la regla que relaciona cuatro cosas de un gas: presión, volumen, cantidad (moles) y temperatura.',
 ['dan moles ($2$), temperatura ($273,15$ K) y presión ($1$ atm)','dan la constante $R$ en el enunciado','piden el volumen que ocupa el gas'],
 [('Cálculos de reacciones (estequiometría)','Se parece porque usa moles. Pero aquí no hay ninguna reacción química, solo un gas quieto.'),('Leyes de Boyle o Charles','Se parecen porque hablan de gases. Pero esas cambian solo dos cosas y dejan el resto fijo; aquí se usan las cuatro juntas, con la ecuación completa.')],
 ['Escribo la ecuación: presión por volumen igual a moles por $R$ por temperatura.','Como piden el volumen, lo dejo solo: volumen = moles × $R$ × temperatura ÷ presión.','Reemplazo con los datos: $2$ × $0,082$ × $273,15$ ÷ $1$.','Hagamos la cuenta con calculadora y pongo litros (L).'])
E('cie-009','Ecología: depredadores y presas','Es ver cómo dos poblaciones se afectan entre sí: los depredadores comen presas, y si cambia una, cambia la otra.',
 ['hay dos poblaciones: depredadores y presas','piden qué pasa con las presas si los depredadores mueren más','es un modelo, o sea una explicación con letras ($\\gamma$, $\\delta$)'],
 [('Crecimiento de una sola población','Se parece porque también habla de cuántos individuos hay. Pero aquí son dos poblaciones que se afectan una a la otra.'),('Cadena alimenticia','Se parece porque aparece quién se come a quién. Pero no piden dibujar la cadena, sino el efecto de un cambio.')],
 ['Me pregunto qué significa que los depredadores mueran más: habrá menos depredadores.','Pienso qué les pasa a las presas con menos depredadores: se las comen menos.','Reviso la fórmula del equilibrio de las presas, $\\gamma/\\delta$, y veo qué pasa si $\\gamma$ aumenta.','Elijo la opción que coincide con mi razonamiento.'])
E('mat-001','Matemáticas: función lineal (un cobro fijo más un cobro por cada unidad)','Es cuando algo se paga con dos partes: una cantidad que pagas siempre, y otra que va creciendo parejo, como un taxi.',
 ['hay un cobro de arranque que se paga siempre: 4.000 pesos','hay un cobro por cada kilómetro: 1.000 pesos','piden el precio de un recorrido concreto: 7 km'],
 [('Proporcionalidad directa','Se parece porque el precio sube con los kilómetros. Pero en la proporcional, con $0$ km pagarías $0$; aquí con $0$ km ya debes 4.000 por el arranque.'),('Porcentajes','Se parece porque son cuentas de plata. Pero no hay ningún "por ciento" en el enunciado.')],
 ['Separo lo que se paga una sola vez (arranque: 4.000) de lo que se paga por cada kilómetro (1.000).','Multiplico los kilómetros por lo que cuesta cada uno: $7$ × 1.000 = 7.000.','Le sumo el arranque: 7.000 + 4.000 = 11.000.','Compruebo con un caso fácil: con $0$ km pagaría 4.000, que es el arranque. Tiene sentido.'])
E('mat-002','Matemáticas: función cuadrática (puntos donde corta el eje x)','Es una función con $x^2$ cuya gráfica es una curva en forma de U. Aquí piden dónde esa curva cruza la línea horizontal.',
 ['la función tiene un $x^2$: eso la hace cuadrática','dice "corta el eje $x$": es donde la curva toca la línea horizontal','en esos puntos la altura es $0$'],
 [('Vértice','Se parece porque es la misma curva. Pero el vértice es el punto más alto o más bajo, y no lo están pidiendo.'),('Corte con el eje y','Se parece porque también es un corte. Pero ese se saca poniendo $x=0$; aquí piden el corte con el eje $x$.')],
 ['Como en el corte la altura es cero, escribo $x^2-4x+3=0$.','Busco dos números que multiplicados den $3$ y sumados den $-4$: son $-1$ y $-3$.','Escribo $(x-1)(x-3)=0$; cada paréntesis puede valer cero.','Entonces $x=1$ o $x=3$. Compruebo: $1-4+3=0$. Sí cumple.'])
E('mat-003','Matemáticas: probabilidad simple','Es medir qué tan posible es que pase algo: se cuentan las formas en que puede salir lo que quiero y se comparan con todas las formas en que puede salir.',
 ['hay una bolsa con fichas de colores','sacan una al azar (a la suerte)','piden la probabilidad de que sea roja'],
 [('Conteos y arreglos (combinatoria)','Se parece porque también se cuenta. Pero aquí no piden de cuántas maneras se ordenan las fichas, solo la probabilidad de una.'),('Promedios (estadística)','Se parece porque hay números. Pero aquí no hay lista de datos para promediar, hay azar.')],
 ['Cuento cuántas fichas hay en total: $3$ rojas + $5$ azules = $8$.','Cuento las que me sirven, las rojas: $3$.','Pongo las que me sirven sobre el total: $3$ de $8$, o sea $\\tfrac{3}{8}$.','Reviso que sea menor que $1$ y que no haya contado de más.'])
E('mat-004','Matemáticas: estadística (media y mediana)','Es resumir una lista de datos con un solo número: la media es el promedio y la mediana es el dato que queda en el medio cuando los pones en orden.',
 ['hay una lista de datos: $2, 3, 3, 4, 8$','mencionan la media y la mediana','preguntan qué pasa con ellas al quitar un dato'],
 [('Probabilidad','Se parece porque hay números. Pero aquí no hay azar ni se saca nada a la suerte; solo se quita un dato de la lista.'),('Moda','Se parece porque también resume datos. Pero la moda (el dato más repetido) no la mencionan.')],
 ['Quito el $8$ y me queda: $2, 3, 3, 4$.','Media nueva: sumo $2+3+3+4=12$ y divido entre $4$: da $3$. Bajó de $4$ a $3$.','Mediana nueva: con $4$ datos, es el promedio de los dos del medio ($3$ y $3$): da $3$. No cambió.','Elijo la opción que dice: la media baja a $3$ y la mediana no cambia.'])
E('mat-005','Matemáticas: probabilidad con dos dados','Es lo mismo que la probabilidad simple, pero con dos dados: hay que contar todas las parejas posibles que pueden salir.',
 ['se lanzan dos dados','piden que la suma sea $7$','hay que contar parejas, no solo números sueltos'],
 [('Probabilidad con un solo dado','Se parece porque son dados. Pero con uno hay $6$ resultados; con dos hay $6\\cdot6=36$ parejas.'),('Conteos y arreglos (combinatoria)','Se parece porque se cuenta. Pero aquí basta con listar las parejas que suman $7$ y compararlas con el total.')],
 ['Calculo cuántas parejas existen en total: $6$ × $6$ = $36$.','Escribo las que suman $7$: $(1,6)$, $(2,5)$, $(3,4)$, $(4,3)$, $(5,2)$, $(6,1)$. Son $6$.','Pongo las que sirven sobre el total: $\\tfrac{6}{36}$.','Simplifico dividiendo entre $6$: queda $\\tfrac{1}{6}$.'])
E('mat-006','Matemáticas: porcentajes seguidos (sube y luego baja)','Es cuando un precio cambia varias veces seguidas en porcentaje. Cada cambio se calcula sobre el precio que había justo antes.',
 ['el artículo cuesta 100.000 pesos','primero sube $20\\%$ y después baja $20\\%$','piden el precio final'],
 [('Un aumento simple','Se parece porque hay un porcentaje. Pero aquí son dos cambios, y el segundo se calcula sobre el precio nuevo, no sobre el original.'),('Regla de tres','Se parece porque es de plata. Pero no se resuelve con una sola proporción, hay que hacer el cambio dos veces.')],
 ['Calculo la subida: el $20\\%$ de 100.000 es 20.000; el precio queda en 120.000.','Ahora la bajada es sobre 120.000: el $20\\%$ de 120.000 es 24.000.','Resto: 120.000 − 24.000 = 96.000.','Veo que no volvió a 100.000: subir y bajar el mismo porcentaje no se cancela.'])
E('lec-001','Lectura: encontrar la idea que defiende el autor','Es descubrir qué quiere decir el autor con todo el texto, y qué opinión defiende o rechaza.',
 ['la pregunta dice "¿qué cuestiona el autor?": quiere saber contra qué está','el texto tiene la palabra "engañoso": es una crítica','la idea importante viene después de "Por eso"'],
 [('Hacer un resumen','Se parece porque hay que entender el texto. Pero no piden contar todo lo que dice, sino la idea que el autor critica.'),('Significado de una palabra','Se parece porque lees el texto. Pero nadie pregunta qué significa una palabra.')],
 ['Leo el texto completo una vez, sin afán.','Busco la palabra que anuncia la conclusión: aquí es "Por eso".','Leo lo que viene después: dice que medir las bibliotecas solo por préstamos es engañoso.','Elijo la opción que dice eso mismo con otras palabras, y descarto las que hablan de otra cosa.'])
E('lec-002','Lectura: conectores (palabras que unen ideas)','Los conectores son palabras como "por lo tanto", "sin embargo" o "además", que dicen cómo se relacionan dos ideas.',
 ['hay una frase con un espacio en blanco para completar','las opciones son conectores, no palabras normales','las dos ideas son: "llovió toda la noche" y "el partido se jugó"'],
 [('Ortografía','Se parece porque hay que completar una frase. Pero todas las opciones están bien escritas; lo que cambia es el sentido.'),('Idea principal','Se parece porque es lectura. Pero nadie pregunta de qué trata la frase, sino cómo se unen las dos partes.')],
 ['Leo las dos ideas por separado: "llovió toda la noche" y "el partido se jugó".','Me pregunto qué esperaría uno: si llueve, uno esperaría que el partido se cancele.','Pero se jugó igual. Entonces las dos ideas se oponen, una contradice lo que esperaba.','Para oposición sirve "sin embargo". Pruebo la frase completa y suena bien.'])
E('lec-003','Razonamiento lógico: sacar una conclusión','Es partir de una regla y un dato para deducir algo que el texto no dice, pero que obligatoriamente es cierto.',
 ['hay una regla general: "todos los que entregaron aprobaron"','hay un dato: "Camila no aprobó"','piden qué se puede concluir'],
 [('Comprensión literal','Se parece porque hay que leer con cuidado. Pero la respuesta no está escrita, hay que deducirla.'),('Dar una opinión','Se parece porque preguntan por Camila. Pero no importa lo que tú creas de ella, solo lo que la regla obliga.')],
 ['Escribo la regla así: entregó → aprobó.','Miro el dato: Camila no aprobó.','Pienso: si hubiera entregado, habría aprobado. Pero no aprobó, así que no entregó.','Elijo la opción que dice eso y descarto las que inventan cosas, como "perdió por mala nota".'])
E('ing-003','Inglés: entender un aviso','Es leer un aviso corto, como un letrero, y encontrar el dato que responde la pregunta.',
 ['hay un letrero con horarios (Monday–Friday, 8 a.m.–6 p.m.)','dice "Closed on holidays" (cerrado en festivos)','la pregunta es si puedes ir un domingo'],
 [('Gramática','Se parece porque está en inglés. Pero nadie te pide completar frases.'),('Vocabulario suelto','Se parece porque hay palabras nuevas. Pero hay que entender todo el aviso, no una sola palabra.')],
 ['Leo el aviso y subrayo los días: Monday–Friday es de lunes a viernes.','Me pregunto: ¿el domingo (Sunday) está dentro de lunes a viernes? No.','Entonces el domingo está cerrado.','Elijo la opción que dice "No, it is not open on Sunday".'])
E('soc-001','Sociales: la Constitución de 1991 y la tutela','Es conocer para qué sirven las herramientas que la Constitución de 1991 le dio a las personas para defender sus derechos.',
 ['nombran la acción de tutela','dicen que la creó la Constitución de 1991','preguntan para qué sirve'],
 [('Ramas del poder','Se parece porque es la misma Constitución. Pero nadie pregunta quién hace las leyes ni quién las aplica.'),('Elecciones','Se parece porque es de derechos políticos. Pero la tutela no sirve para elegir a nadie.')],
 ['Recuerdo qué es la tutela: un recurso rápido que cualquier persona puede usar.','Recuerdo para qué: para pedir que un juez proteja un derecho fundamental que está en peligro.','Reviso las opciones y descarto las que hablan de leyes, elecciones o guerra.','Elijo la que habla de proteger derechos de forma inmediata.'])
E('soc-002','Sociales: ramas del poder público','Colombia divide el poder en tres ramas, y cada una tiene un trabajo distinto: hacer las leyes, aplicarlas y juzgar.',
 ['preguntan por una "rama del poder público"','preguntan qué rama hace las leyes'],
 [('Mecanismos de participación','Se parece porque es de la Constitución. Pero esos son herramientas de los ciudadanos, como el voto, y no se preguntan aquí.'),('Elecciones','Se parece porque el Congreso se elige. Pero no preguntan cómo se elige, sino qué función tiene.')],
 ['Recuerdo las tres ramas: Ejecutiva (gobierna), Legislativa (hace las leyes) y Judicial (juzga).','Veo qué función piden: hacer las leyes.','La que hace las leyes es el Congreso, o sea la rama Legislativa.','Descarto Ejecutiva y Judicial, y compruebo que "Electoral" no es una de las tres ramas clásicas.'])
E('soc-003','Historia: tipos de fuentes','Una fuente es todo lo que sirve para estudiar el pasado. Puede ser primaria (de la época) o secundaria (escrita después, sobre esa época).',
 ['hablan de una carta escrita en 1810','dicen que la escribió un testigo de los hechos','piden qué tipo de fuente es'],
 [('Ordenar hechos en el tiempo','Se parece porque hay una fecha. Pero nadie pide poner hechos en orden.'),('Causas de la independencia','Se parece porque es de la misma época. Pero el tema es qué clase de documento es, no lo que cuenta.')],
 ['Me pregunto: ¿quién lo escribió y cuándo?','Lo escribió alguien que estuvo ahí, en 1810, en el momento de los hechos.','Entonces es una fuente primaria: viene directo de la época.','Descarto "secundaria" (escrita después) y las opciones que no son fuentes.'])
E('soc-004','Historia: ordenar hechos en el tiempo','Es poner los hechos en una línea del tiempo, del más antiguo al más reciente.',
 ['la pregunta dice "orden cronológico"','todas las opciones tienen los mismos cuatro hechos, solo cambian de lugar'],
 [('Causas y consecuencias','Se parece porque son hechos históricos. Pero no piden explicar por qué pasó cada uno, solo el orden.'),('Tipos de fuentes','Se parece porque es historia. Pero no hablan de documentos.')],
 ['Busco la fecha de cada hecho: Grito de Independencia, $1810$; Constitución, $1886$; Frente Nacional, $1958$–$1974$; nueva Constitución, $1991$.','Los ordeno de menor a mayor año.','Reviso cada opción y la comparo con mi lista.','Elijo la que coincide exactamente.'])
E('ing-001','Inglés: presente simple (cosas que haces siempre)','El presente simple se usa para rutinas y hábitos. Con he, she o it, el verbo lleva una -s o -es al final.',
 ['"every day" (todos los días) habla de una rutina','el sujeto es "She": una sola persona, tercera persona','falta el verbo'],
 [('Presente continuo','Se parece porque también es presente. Pero el continuo habla de lo que pasa ahora mismo y lleva "is" y -ing; aquí hay una rutina.'),('Pasado o perfecto','Se parece porque es un verbo. Pero nada en la frase indica que ya pasó.')],
 ['Veo el sujeto: "She", una sola persona.','Veo que es una rutina por "every day".','Con she, el verbo lleva -s o -es: go se vuelve goes.','Leo la frase completa: "She goes to school every day". Suena bien.'])
E('ing-002','Inglés: primer condicional (algo que puede pasar)','Se usa para decir qué pasará si ocurre algo posible. La parte con "if" va en presente y el resultado lleva will.',
 ['empieza con "If it rains tomorrow" (algo posible en el futuro)','el espacio está en la segunda parte: el resultado','la palabra tomorrow indica futuro'],
 [('Segundo condicional','Se parece porque también lleva if. Pero ese es para cosas imaginarias o improbables y usa would; aquí llover es algo real y posible.'),('Tiempos pasados','Se parece porque son verbos. Pero tomorrow es futuro, no puede ir en pasado.')],
 ['Veo la parte con if: "If it rains" está en presente. Eso es lo normal.','Me fijo en que el resultado necesita will más el verbo.','Busco la opción con will: "will stay".','Leo completo: "If it rains tomorrow, we will stay at home". Perfecto.'])
E('ing-004','Inglés: vocabulario según el contexto','Es elegir la palabra que tiene sentido en la frase, aunque otras se parezcan.',
 ['dice "from the library" (de la biblioteca)','dice "for two weeks" (por dos semanas): es temporal','las opciones son verbos con significados distintos'],
 [('Gramática','Se parece porque es una frase para completar. Pero las opciones no cambian la forma del verbo, cambian su significado.'),('Comprar o vender','Se parece porque son verbos de dar y recibir. Pero una biblioteca no vende libros: los presta.')],
 ['Me pregunto quién da y quién recibe: la biblioteca da, tú recibes.','Veo que es por dos semanas, o sea prestado.','Recuerdo que borrow es recibir prestado, y lend es dar prestado.','Elijo borrow.'])
json.dump(E_,open('content/enfoques.json','w'),ensure_ascii=False,indent=1)
print(len(E_))
